def fill(ti, rows):
    table = d.tables[ti]
    for ri, vals in enumerate(rows, 1):
        if ri >= len(table.rows):
            break
        for ci, val in enumerate(vals):
            if ci >= len(table.columns): break
            cell = table.cell(ri, ci)
            if not cell.text.strip():
                cell.text = val

